import{_ as a,o as s,c as n,a0 as t}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Internal Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),r={name:"architecture.md"};function p(i,e,l,o,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="internal-architecture" tabindex="-1">Internal Architecture <a class="header-anchor" href="#internal-architecture" aria-label="Permalink to &quot;Internal Architecture&quot;">​</a></h1><p>Mamba is not interpreted; it is a full language compiler.</p><h2 id="the-compilation-pipeline" tabindex="-1">The Compilation Pipeline <a class="header-anchor" href="#the-compilation-pipeline" aria-label="Permalink to &quot;The Compilation Pipeline&quot;">​</a></h2><p>When you run <code>./mamba build app.mb --release</code>, Mamba goes through several stages:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mamba Source Code (*.mb)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    Preprocessor (Resolves imports, merges files)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    Parser (Lark LALR Grammar Parser)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    AST (Abstract Syntax Tree)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    Target Generator (e.g., C++20)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    clang++ (Native Compilation with -O3 flag)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    Standalone Executable (Native Binary)</span></span></code></pre></div><h3 id="compiler-modules-reference" tabindex="-1">Compiler Modules Reference <a class="header-anchor" href="#compiler-modules-reference" aria-label="Permalink to &quot;Compiler Modules Reference&quot;">​</a></h3><ul><li><strong><code>preprocessor.py</code></strong>: Handles <code>#import</code> or <code>import &quot;file.mb&quot;</code> directives.</li><li><strong><code>builder.py</code></strong>: The core driver orchestrating AST parsing and code generation.</li><li><strong><code>targets/cpp.py</code></strong>: Emits highly-optimized C++ source code.</li><li><strong><code>targets/php.py</code></strong>: Emits PHP script representations.</li></ul><h2 id="native-web-server-architecture" tabindex="-1">Native Web Server Architecture <a class="header-anchor" href="#native-web-server-architecture" aria-label="Permalink to &quot;Native Web Server Architecture&quot;">​</a></h2><p>The C++ executable generated by Mamba embeds a custom POSIX socket HTTP server.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Incoming Connection</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>     Socket</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>   HTTP Parser</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  Request Object</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>   Worker Queue</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span> 20 Worker Threads (std::thread pool)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>   Mamba Route</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>    Response</span></span></code></pre></div><h3 id="key-performance-attributes" tabindex="-1">Key Performance Attributes <a class="header-anchor" href="#key-performance-attributes" aria-label="Permalink to &quot;Key Performance Attributes&quot;">​</a></h3><ul><li><strong>Thread Pool:</strong> Automatically scales to hardware concurrency limits to process requests simultaneously.</li><li><strong>CORS Handling:</strong> Natively responds to <code>OPTIONS</code> preflight checks.</li><li><strong>Thread Safety:</strong> Integrates SQLite <code>std::mutex</code> locking behind the scenes to ensure database operations are safe under extreme concurrent load.</li></ul>`,12)])])}const m=a(r,[["render",p]]);export{u as __pageData,m as default};
